-- =========================================================
-- CricSavant AI -- seed player_pool with the official IPL 2026
-- mini-auction shortlist (369 players, BCCI-published).
-- =========================================================
-- Source: insidesport.in, published Dec 16 2025, sourced from BCCI's
-- official auction shortlist release. This is REFERENCE data from the
-- most recent CONCLUDED auction (Dec 16 2025, Abu Dhabi) -- these
-- players are already contracted to real teams for the season that just
-- finished. IPL 2027's actual pool does not exist yet. This dataset is
-- what lets the app demonstrate full mechanics (search, recommend, buy,
-- track budget) against real, accurate, citable data rather than
-- fabricated names -- swap in the 2027 pool the moment BCCI publishes it.

CREATE TABLE IF NOT EXISTS player_pool (
    pool_id              BIGSERIAL PRIMARY KEY,
    auction_year          INT NOT NULL,
    sr_no                 INT,
    set_code              TEXT,
    player_name           TEXT NOT NULL,
    country               TEXT NOT NULL,
    age                   INT,
    role                  TEXT NOT NULL CHECK (role IN ('batter','bowler','all-rounder','wicketkeeper')),
    bowling_style         TEXT NOT NULL DEFAULT 'na' CHECK (bowling_style IN ('pace','spin','na')),
    capped_status         TEXT NOT NULL CHECK (capped_status IN ('capped','uncapped')),
    is_overseas           BOOLEAN NOT NULL,
    base_price_lakh       NUMERIC(10,2) NOT NULL,
    is_current_reference  BOOLEAN NOT NULL DEFAULT TRUE,
    source_url            TEXT NOT NULL,
    created_at            TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_player_pool_name ON player_pool (player_name);
CREATE INDEX IF NOT EXISTS idx_player_pool_role ON player_pool (role, is_overseas);

